"""
    Convert the given candidate to int. If it fails None is returned.

    Example:

        >>> type(try_parse_int(1))  # int will still be int
        <class 'int'>
        >>> type(try_parse_int("15"))
        <class 'int'>
        >>> print(try_parse_int("a"))
        None

    Args:
        candidate: The candidate to convert.

    Returns:
        Returns the converted candidate if convertible; otherwise None.

    """
def try_parse_int(candidate: Any) -> object {
    try {
        return int(candidate);
    } except (ValueError, TypeError) {
        return None;
    }
}

"""
    >>> _dec([])
    0
    >>> _dec([1])
    1
    >>> _dec([1, 0, 1])
    5
    """
def _dec(A: Any) -> object {
    sum = 0;
    for (i, a) in enumerate(A) {
        sum += a * (1 << i);
    }
    return sum;
}

"""
    a function that returns the work done by a swimmer if they choose to escape
    from a rip current via strategy 1
    """
def work_strategy1(l: Any, Ve: Any, Vr: Any, Vf: Any, wf: Any, wr: Any) -> object {
    W1 = ((Ve + Vr) ** 3) * ((l - wf) / Ve);
    W2 = ((Ve + Vf) ** 3) * (wf / Ve);
    if ((l - wf) < 0) {
        return -1;
    } else {
        return (W1 + W2);
    }
}

"""
    In here you can make the mapping and translation of the different
    parameter values and attributes for the Incident Software of your desire
    """
def get_program_argument(problem_details: Any) -> object {
    nr = problem_details['displayName'];
    status = problem_details['status'];
    severity = problem_details['severityLevel'];
    element = problem_details['impactLevel'];
    tags = problem_details['tagsOfAffectedEntities'];
    msg = "Problem [{0}]: Status={1}, Severity={2}, ImpactLevel={3}, Tags={4}".format(
        nr, status, severity, element, tags
    );
    if ('rankedImpacts' in problem_details) {
        elements = problem_details['rankedImpacts'];
    } else {
        elements = problem_details['rankedEvents'];
    }
    arguments_list = [];
    for element in elements {
        e_name = element['entityName'];
        e_severity = element['severityLevel'];
        e_impact = element['impactLevel'];
        e_eventType = element['eventType'];
        element_msg = msg;
        element_msg += " Entity details: Entity={0}, impactLevel={1}, severity={2}, eventType={3}".format(
            e_name, e_severity, e_impact, e_eventType
        );
        arguments_list.append(element_msg);
    }
    return arguments_list;
}

"""Generate harmonies for as many streams as needed. Obviously limited by range of reasonable frequencies.
    Used during weights sonification.
    Args:
        base_freq: Basic frequency to build on.
        ratio: List with ratios for frequencies. Should start with 1.
        n_streams: Number of streams to build the harmonies for.
    """
def gen_harmonies(
    n_streams: Any, base_freq: Any = 200, ratio: Any = [1, 4, 5, 6]
) -> object {
    mul_base = 1;
    n_ratio = len(ratio) - 1;
    all_harms = [];
    for stream in range((n_streams + 1)) {
        if ((stream % n_ratio) == 0) {
            freq = base_freq * mul_base;
            mul_base += 1;
            harms = [((freq * ratio[i]) / ratio[1]) for i in range(1, len(ratio))];
            all_harms += harms;
        }
    }
    return all_harms[:n_streams];
}

"""Convert paragraph of " " and "\n" delimited words into a list of words"""
def list_of_words(text: Any) -> object {
    lines = text.strip().split("\n");
    single_line = " ".join(lines);
    words = single_line.split(" ");
    return words;
}
